    // GOOGLE TRANSLATE
    //---------------------------------------------------------------------------------------------
    googleTranslate: function () {
      // Attach something for google to inject into
      $("nav.footer--toolbar ul").append(
        '<li><div id="google_translate"></div></li>'
      );
    },

