    //---------------------------------------------------------------------------------------------
    // Alter event category URLs
    //---------------------------------------------------------------------------------------------
    alterEventCatUrls: function () {
      var pathArray = window.location.pathname.split("/");
      if (pathArray[1] === "events") {
        var ul = document.getElementById("event-category-links");

        if (typeof ul != "undefined" && ul != null) {
          var items = ul.getElementsByTagName("li");
          for (var i = 0; i < items.length; ++i) {
            items[i].firstChild.href = "/events#events-listing";
          }
          $(".event-category-link > a").click(function () {
            var searchCategory = $(this).text();
            localStorage.setItem("event_category", searchCategory);
          });
        }
      }
    },

    //---------------------------------------------------------------------------------------------
    // Event Redirect
    //---------------------------------------------------------------------------------------------

    eventRedirect: function () {
      if (window.location.href.indexOf("/events/") > -1) {
        var container = $("#block-sanjose-content");
        var mainText = $("#block-sanjose-content").text();
        var pathname = window.location.href;
        var pathSplit = pathname.split("/");
        var forwardTo = "http://" + pathSplit[2] + "/events";
        if (
          mainText.indexOf("You are not authorized to access this page.") >
            -1 ||
          mainText.indexOf("404 - PAGE NOT FOUND") > -1
        ) {
          window.location.replace(forwardTo);
        }
      }
    },

    //---------------------------------------------------------------------------------------------
    // SAFARI GTM FIX
    //---------------------------------------------------------------------------------------------
    safariGTMFix: function () {
      $('body[browser="Safari"] a[target="_blank"]').click(function () {
        event.preventDefault();
        event.stopPropagation();

        var linkTarget = $(this).attr("href");
        //console.log(linkTarget);

        var win = window.open(linkTarget, "_blank");
        win.focus();
      });
    },

    //---------------------------------------------------------------------------------------------
    // DOM READY (TO TRIGGER ANIMATIONS) -- KEEP THIS AS LAST JS FUNCTION
    //---------------------------------------------------------------------------------------------
    domReady: function () {
      // Attach window events
      $(window).on("load", function () {
        $("body").addClass("ready");

        $(
          "#google_translate .goog-te-gadget .goog-te-gadget-simple > span > a"
        ).removeAttr("href");
      });
    },
