/**
 * Accordion Component Interactions
 */
(function ($) {
  'use strict';

  function getAccordionBySlug(slug) {
    if (!slug) return $();
    return $('.accordion-item[data-slug="' + slug + '"]').first();
  }

  function smoothScrollTo($el, isSmooth, offsetPadding) {
    if (!$el || !$el.length) return;

    var offset = offsetPadding || 0;
    var marginTop = parseInt($el.css('scroll-margin-top')) || 110;
    var targetTop = $el.offset().top - offset - marginTop;

    if (isSmooth) {
      $('html, body').animate({ scrollTop: targetTop }, 400);
    } else {
      window.scrollTo(0, targetTop);
    }
  }

  function handleAccordionClick($target, isSmooth) {
    var isExpanded = $target.hasClass('is-expanded');

    // If already expanded, just smooth scroll to it
    if (isExpanded) {
      smoothScrollTo($target, isSmooth, 0);
      return;
    }

    var targetTopBefore = $target.offset().top;
    var heightToLose = 0;

    // Calculate height lost from currently expanded items above our target
    $('.accordion-item.is-expanded').each(function () {
      var $current = $(this);
      if ($current.offset().top < targetTopBefore) {
        heightToLose += $current.find('.accordion-content').outerHeight(true) || 0;
      }
      $current.removeClass('is-expanded');
    });

    $target.addClass('is-expanded');
    smoothScrollTo($target, isSmooth, heightToLose);

    // Update URL hash without causing a page jump
    var slug = $target.data('slug');
    if (slug && history.pushState) {
      history.pushState(null, null, '#' + slug);
    }
  }

  $(document).ready(function () {

    // 1. Handle Navigation/Load with Hash
    if (window.location.hash) {
      var hash = window.location.hash.replace('#', '');
      var $target = getAccordionBySlug(hash);

      // Direct ID fallback
      if (!$target.length) {
        $target = $('#' + hash + '.accordion-item');
      }

      if ($target.length) {
        // Prevent browser's native jump
        if (history.scrollRestoration) {
          history.scrollRestoration = 'manual';
        }

        $('.accordion-item').removeClass('is-expanded');
        $target.addClass('is-expanded');

        // Temporarily remove hash from URL so the browser DOES NOT natively jump when load finishes
        // (Permanently removed based on user request)
        if (window.location.hash && history.replaceState) {
          history.replaceState(null, null, window.location.pathname + window.location.search);
        }

        // Scroll immediately to avoid flicker and wait delays
        setTimeout(function () {
          smoothScrollTo($target, false, 0);
        }, 10);

        // Fallback adjustments once all images/resources load
        $(window).on('load', function () {
          setTimeout(function () {
            smoothScrollTo($target, false, 0);
          }, 50); // slight delay to ensure browser layout is stable
        });
      }
    }

    // Prevent native link redirects forcefully by unsetting the href
    // for ANY thumbnail that has a corresponding accordion on THIS page.
    $('.accordion-thumbnail-link').each(function () {
      var slug = $(this).data('accordion-target');
      var $target = getAccordionBySlug(slug);

      if ($target.length > 0) {
        // Physically remove the href so the browser simply cannot redirect
        $(this).removeAttr('href');
        // Ensure it is still keyboard accessible and behaves like a button
        $(this).attr('tabindex', '0');
        $(this).attr('role', 'button');
        $(this).css('cursor', 'pointer');
      }
    });

    // 2. Thumbnail / Link Click Handling
    $(document).on('click', '.accordion-thumbnail-link', function (e) {
      var slug = $(this).data('accordion-target');
      var $target = getAccordionBySlug(slug);

      // Priority on same page: Open accordion instead of redirecting
      if ($target.length > 0) {
        e.preventDefault();
        e.stopImmediatePropagation();
        handleAccordionClick($target, true);
      }
      // If NOT on same page (so it still has href), let normal link navigation proceed!
    });

    // Allow keyboard 'Enter' mapping for the unset thumbnails
    $(document).on('keypress', '.accordion-thumbnail-link', function (e) {
      if (e.which === 13) {
        $(this).click();
      }
    });

    // 3. Accordion Header Toggle
    $(document).on('click', '.accordion-header', function () {
      var $item = $(this).closest('.accordion-item');

      if ($item.hasClass('is-expanded')) {
        $item.removeClass('is-expanded');
        if (history.pushState) {
          history.pushState(null, null, window.location.pathname + window.location.search);
        }
      } else {
        handleAccordionClick($item, true);
      }
    });

  });
})(jQuery);
