(function ($) {
  $(".display-type-holiday").each(function () {
    $this = $(this);
    if ($this.text().indexOf("4x4") > -1)
      $this.closest(".block-list").addClass("four-by-four");
    else if ($this.text().indexOf("3x4") > -1)
      $this.closest(".block-list").addClass("three-by-four");
    else if ($this.text().indexOf("2x4") > -1)
      $this.closest(".block-list").addClass("two-by-four");
    else $this.closest(".block-list").addClass("none");
  });

  $(function ($) {
    var x = 8;
    $(".two-by-four .block-list--items").each(function () {
      $(this).find("li").slice(0, 8).show();
      let length = $(this).find("li").length;
      if (length <= x) {
        $(this).parent().find(".load-more").hide();
      }
    });
    $(".two-by-four .load-more").on("click", function (e) {
      e.preventDefault();
      x = x + 8;
      $(this).parent().prev().find("li").slice(0, x).slideDown();
      if ($(this).parent().prev().find("li").length <= x) {
        $(this).closest(".load-more").hide();
      }
    });
  });

  $(function ($) {
    var x = 12;
    $(".three-by-four .block-list--items").each(function () {
      $(this).find("li").slice(0, 12).show();
      let length = $(this).find("li").length;
      if (length <= x) {
        $(this).parent().find(".load-more").hide();
      }
    });
    $(".three-by-four .load-more").on("click", function (e) {
      e.preventDefault();
      x = x + 12;
      $(this).parent().prev().find("li").slice(0, x).slideDown();
      if ($(this).parent().prev().find("li").length <= x) {
        $(this).closest(".load-more").hide();
      }
    });
  });

  $(function ($) {
    var x = 16;
    $(".four-by-four .block-list--items").each(function () {
      $(this).find("li").slice(0, 16).show();
      let length = $(this).find("li").length;
      if (length <= x) {
        $(this).parent().find(".load-more").hide();
      }
    });
    $(".four-by-four .load-more").on("click", function (e) {
      e.preventDefault();
      x = x + 16;
      $(this).parent().prev().find("li").slice(0, x).slideDown();
      if ($(this).parent().prev().find("li").length <= x) {
        $(this).closest(".load-more").hide();
      }
    });
  });
  $(function ($) {
    $(".none .block-list--items").each(function () {
      $(this).find("li").show();
      $(this).parent().find(".load-more").hide();
    });
    $(".none .load-more").on("click", function (e) {
      e.preventDefault();
      $(this).closest(".load-more").hide();
    });
  });
})(jQuery);

