(function ($) {

  var angularApp  = jQuery('.angular-app');
  if(angularApp.length > 0 ){
    jQuery('head').append('<base href="/" />');
  }

  var AttractionListingApp = angular.module('AttractionListingApp', ['ngSanitize', 'NgPager', 'angular-scroll-animate','angularMoment', 'ngStorage']).run(function (PagerConfig) {
    PagerConfig.setBase1();
  }).config(function ($interpolateProvider) {
    $interpolateProvider.startSymbol('{[{').endSymbol('}]}');
  }).config(function($locationProvider) {
    $locationProvider.html5Mode(true);
  });

  AttractionListingApp.controller('AttractionListingController', function ($scope, $http, $sce, $timeout, moment, $localStorage, $location ) {


    $scope.taxonomyTermId = taxonomyTermId;
    $scope.showViewAllButton = true;
    $scope.listingList = [];
    $scope.filteredList = [];
    $scope.newListingList = [];
    $scope.orderByValue = '';
    $scope.itemsPerPage = 8;
    $scope.startFrom = 0;

    $scope.init = function () {
      $scope.initListingList();
    };

    $scope.getHtml = function (x) {
      return $sce.trustAsHtml(x);
    };

    $scope.getItemNumber = function (index) {
      return (index + 1) + (($scope.currentPage - 1) * $scope.itemsPerPage);
    };

    $scope.$watchCollection('filteredList ', function () {
      if ($scope.filteredList.length > 0) {
        $scope.totalPages = Math.ceil($scope.filteredList.length / $scope.itemsPerPage);
      }
    });

    $scope.viewAllClick = function () {
      $scope.isViewAll = true;
      $scope.showViewAllButton = false;
      $scope.itemsPerPage = $scope.filteredList.length;
    };

    $scope.initListingList = function () {
      $http.get("/attraction-category-grid/" + $scope.taxonomyTermId).then(function mySuccess(response) {
        $scope.listingList = response.data;
        $scope.originalListingList = angular.copy($scope.listingList);
      }, function myError(response) {

      });
    };

    //Paging

    $scope.paged = function (newPage) {
      $scope.startFrom = (newPage -1) * $scope.itemsPerPage;
      $scope.currentPage = newPage;
      // $location.search('page', $scope.currentPage);
      // window.location.href = window.location.pathname + '?page=' + $scope.currentPage;


      if (history.pushState) {
        var newurl = window.location.origin + window.location.pathname + '?page=' + $scope.currentPage;
        window.history.pushState(null,'',newurl);

        // history.pushState(null, '', '/foo?bar=true')
      }

      jQuery('html,body').animate({scrollTop: $scope.offset.top},1000);
    };

    $scope.currentPage = 1;

    $scope.maxPagesToDisplay = 5;

    //Scroll To
    $scope.scrollToElement = function(element){
      setTimeout(function(){
        jQuery('html, body').animate({
          scrollTop: jQuery(element).offset().top
        }, 1000);
      }, 1000);
    };

    $scope.init();

    $scope.animateElementIn = function($el) {
      $scope.imgSrc = $el.attr('data-src');
      $el.attr('src', $scope.imgSrc);
      $el.removeClass('not-visible');
      $el.addClass('animated fadeIn'); // this example leverages animate.css classes
    };

    $scope.animateElementOut = function($el) {
      $el.addClass('not-visible');
      $el.removeClass('animated fadeOut'); // this example leverages animate.css classes
    };

    $scope.getPosition = function() {
      $scope.attractionListing = angular.element('#attractions-listing');
      $scope.offset = $scope.attractionListing.offset();
    };

    $scope.getPosition();


  });

})(jQuery);

