      $scope.initListingList = function () {
        $http.get("/featured-partner-hotel-listings").then(
          function mySucces(response) {
            $scope.listingList = response.data;
            $scope.originalListingList = angular.copy($scope.listingList);
            for (var i = 0; i < $scope.listingList.length; i++) {
              if ($scope.listingList[i].featured === "Partner") {
                var a = $scope.originalListingList[i]; // removes the item
                $scope.featuredListingList.push(a); // adds it back to the beginning
              }
            }
            for (var i = 0; i < $scope.listingList.length; i++) {
              if ($scope.listingList[i].featured !== "Partner") {
                var a = $scope.originalListingList[i]; // removes the item
                $scope.notFeaturedListingList.push(a); // adds it back to the beginning
              }
            }
            $scope.featuredListingList = $scope.shuffleArrayNew(
              $scope.featuredListingList
            );
            if ($scope.featuredListingList.length > 0) {
              $scope.listingList = $scope.featuredListingList.concat(
                $scope.notFeaturedListingList
              );
            }

            $.grep($scope.listingList, function (item, idx) {
              item.conventionDistance = $scope.distance(
                item.lat,
                item.lon,
                $scope.sortOptions.conventioncenter.value.lat,
                $scope.sortOptions.conventioncenter.value.lng,
                "M"
              );
              item.airportDistance = $scope.distance(
                item.lat,
                item.lon,
                $scope.sortOptions.airport.value.lat,
                $scope.sortOptions.airport.value.lng,
                "M"
              );
            });
          },
          function myError(response) {}
        );
      };

      $scope.shuffleArrayNew = function (array) {
        var currentIndex = array.length,
          temporaryValue,
          randomIndex;
        while (0 !== currentIndex) {
          randomIndex = Math.floor(Math.random() * currentIndex);
          currentIndex -= 1;
          temporaryValue = array[currentIndex];
          array[currentIndex] = array[randomIndex];
          array[randomIndex] = temporaryValue;
        }
        return array;
      };

