//-------------------
// Form Validation
//-------------------
(function($) {
  Drupal.behaviors.formValidation = {
    attach: function(context, settings) {
    setTimeout(function() {
      var facilityFrm = $(
        "#webform-submission-facility-use-survey-node-1410-add-form"
      );
      if (facilityFrm.length) {
        $(facilityFrm)
          .find("textarea, input")
          .each(function (i, el) {
            var tagName = $(el).prop("tagName");
            if (/INPUT|TEXTAREA/.test(tagName)) {
              var attrType = $(el).attr("type");
              if (/checkbox|radio/.test(attrType)) {
                $(el).prop("checked", false);
              } else if (
                !/submit|hidden|undefined/.test(attrType) ||
                tagName === "TEXTAREA"
              ) {
                $(el).val("");
              }
            }
          });
      }
    }, 1000);
      $("input[type='submit']").on('click', function(evt) {
        var emptyField = [];
        $("input[required='required']", context).each(function(i) {
          if (!($(this)[0].type == 'checkbox')) {
            if ($.trim($(this).val()) == '') {
              $(this).css("border-color", "red");
              if ($(this).prev()[0].innerText.length > 100) {
                $("label[for=" + this.id + "]").css("color", "red");
                emptyField.push($(this).prev()[0].innerText.slice(0, 100) + '...' + '\n');
              } else {
                if (this.id == 'edit-address-address') {
                  $("label[for=" + this.id + "]").css("color", "red");
                  $(this).closest(".form-composite").children(":first-child").css("color", "red");
                  emptyField.push('Company Address*' + "\n");
                } else {
                  $("label[for=" + this.id + "]").css("color", "red");
                  emptyField.push($(this).prev()[0].innerText + "\n");
                }
              }
            } else {
              $(this).css("border-color", "#00708b");
            }
          } else {
            if (!($(this)[0].checked)) {
              $(this).next().css("color", "red");
              emptyField.push($(this)[0].nextElementSibling.innerText + '\n');
            }
          }
        });
        $("select[required='required']", context).each(function(i) {
          if ($.trim($(this).val()) == '') {
            $(this).css("border-color", "red");
            if ($(this).prev()[0].innerText.length > 100) {
              emptyField.push($(this).prev()[0].innerText.slice(0, 100) + '...' + '\n');
            } else {
              $(this).siblings().css("color", "red");
              emptyField.push($(this).prev()[0].innerText + "\n");
            }
          } else {
            $(this).css("border-color", "#00708b");
          }
        });
        $("textarea[required='required']", context).each(function(i) {
          if ($.trim($(this).val()) == '') {
            $(this).css("border-color", "red");
            if ($(this).parent().prev()[0].innerText.length > 100) {
              $("label[for=" + this.id + "]").css("color", "red");
              emptyField.push($(this).parent().prev()[0].innerText.slice(0, 100) + '...' + '\n');
            } else {
              $("label[for=" + this.id + "]").css("color", "red");
              emptyField.push($(this).parent().prev()[0].innerText + "\n");
            }
          } else {
            $(this).css("border-color", "#00708b");
          }
        });

        var currentNode = '';
        $("fieldset[required='required']", context).each(function(i) {
          var checkboxLen = ''
          var testNode = [];

          if ($(this).find('input:checkbox').length > 0) {
            checkboxLen = $(this).find('input:checkbox').length;
            $(this).find('input:checkbox').each(function(i) {
              currentNode = $(this).parent().parent().siblings().prevObject[0].parentNode.previousElementSibling.innerText;
              if ($(this).prop("checked")) {
                testNode.push(currentNode)
              }
              if (i == checkboxLen - 1 && testNode.length == 0) {
                $(this).closest(".fieldset-wrapper").prev().css("color", "red");
                emptyField.push(currentNode);
              }
            });
          } else if ($(this).find('input:radio').length > 0) {
            checkboxLen = $(this).find('input:radio').length;
            $(this).find('input:radio').each(function(i) {
              currentNode = $(this).parent().parent().siblings().prevObject[0].parentNode.previousElementSibling.innerText;
              if ($(this).prop("checked")) {
                testNode.push(currentNode)
              }
              if (i == checkboxLen - 1 && testNode.length == 0) {
                $(this).closest(".fieldset-wrapper").prev().css("color", "red");
                emptyField.push(currentNode);
              }
            });
          }
        });

        $(".webform-likert-table", context).each(function() {
          if ($(this).siblings().hasClass('form-required')) {
            var current = $(this)[0].parentNode.children[0].innerText;
            $(this).find('tr').each(function(i) {
              var subHeading = ''
              if (i > 0) {
                subHeading = current + "(" + $(this)[0].children[0].innerText + ")";
              }
              var checkNode = [];
              $(this).find('input:radio').each(function() {
                if ($(this).prop("checked")) {
                  checkNode.push(subHeading);
                }
              })
              if (checkNode.length == 0 && subHeading !== '') {
                $(this).css("color", "red");
                $(this).closest(".js-form-type-webform-likert").children().css("color", "red");
                emptyField.push(subHeading);
              }
            })
          }
        });

        $("input[type='file']", context).each(function(i) {
          if ($(this).parent().prev().hasClass('form-required')) {
            if (this.files.length == 0) {
              $("label[for=" + this.id + "]").css("color", "red");
              emptyField.push($(this).parent().prev()[0].innerText + "\n");
            }
          } else if ($(this).parent().prev().prev().hasClass('form-required')) {
            if (this.files.length == 0) {
              if ($(this).parent().prev().prev()[0].innerText != 'Upload Additional Images*') {
                $("label[for=" + this.id + "]").css("color", "red");
                emptyField.push($(this).parent().prev().prev()[0].innerText + "\n");
              }
            }
          }
        });

        var _old = $.unique;
        $.unique = function(arr) {
          if (!!arr[0].nodeType) {
            return _old.apply(this, arguments);
          } else {
            return $.grep(arr, function(v, k) {
              return $.inArray(v, arr) === k;
            });
          }
        };

        if (emptyField.length > 0) {
          if (!($('#myDialog').length)) {
            $("body").prepend("<div id='myDialog' style ='color: red'></div>. ");
          }
          $("#myDialog").empty();
          $("#myDialog").html('<p> ' + $.unique(emptyField).join('</p><p>'));
          $("#myDialog").dialog({
            autoOpen: false,
            modal: true,
            draggable: false,
            show: 'blind',
            hide: 'blind',
            dialogClass: 'jqueryDialog',
            title: "Please complete missing required fields or adjust those that don't meet requirements highlighted in red.",
            buttons: {
              'OK': function() {
                $(this).dialog('close');
              }
            },
            open: function () {
              $('body').addClass('noscroll');
            },
            close: function () {
              $('body').removeClass('noscroll');
            }
          });
          $("#myDialog").dialog("open");
          evt.preventDefault();
        }
      });
    }
  };
})(jQuery);

//--------------------
// GALLERY LAYOUT
//--------------------
(function ($) {

(function($){
	$.fn.wrapChildren = function(options) {
 
        options = $.extend({
		      childElem : undefined,
		      groupSize : 1,
		      wrapper : '<div>'
		    }, options || {});
                             
        if (options.childElem === undefined) return this;
 
        return this.each(function() {
            var elems = $(this).children(),
                len = pos = 0;
             
            elems.each(function(i,value) {
                len += $(value).is(options.childElem)? 1 : 0;                    
                if (len > 0 && (len % options.groupSize === 0) || (i === elems.length - 1)) {          
                  elems.slice(pos,i + 1).wrapAll(options.wrapper);
                  len = 0;
                  pos = i + 1;
                }
            });
        }); 
         
    }
})(jQuery);


$('.gallery').wrapChildren({ childElem : 'li' , groupSize: 5, wrapper : '<ul class="gallery--block">'});
})(jQuery);
