function googleTranslateElementInit() {
	new google.translate.TranslateElement({pageLanguage: 'en', includedLanguages: 'de,es,jv,vi,zh-TW', layout: google.translate.TranslateElement.InlineLayout.SIMPLE}, 'google_translate');
}

// Load the picturefill script asynchronously
(function(d, s, id) {
    var js, fjs = d.getElementsByTagName(s)[0];
    if (d.getElementById(id)) return;
    js = d.createElement(s); js.id = id;
    js.src = "//translate.google.com/translate_a/element.js?cb=googleTranslateElementInit";
    fjs.parentNode.insertBefore(js, fjs);
}(document, 'script', 'googletranslate'));
