var query = document.getElementById("auto-rotate--time")
  ? document.getElementById("auto-rotate--time").innerHTML
  : null;
var value = query ? Number(query.split(" ")[0]) * 1000 : null;

(function ($) {
  $(".hero").each(function () {
    var heroImg = $(this).find("picture source").attr("srcset");
    $(this)
      .find(".hero--event")
      .css("background-image", "url(" + heroImg + ")");

    //Do string character count to determine alternate styling
    var heroCharCount = $(this)
      .find(".hero--content h1.headline-1")
      .text().length;
    if (heroCharCount > 20) {
      $(this).addClass("hero--abbr");
    }

    if ($(".hero--video").length > 0) {
      $(this)
        .delay(700)
        .queue(function (nxt) {
          $(this).find("video").get(0).play();
          nxt();
        });
    }
  });

  $(".hero--content").each(function () {
    var thisParent = $(this).parents(".hero__homepage"),
      thisHeadline = $(this).find(".headline-1").text();

    var hasPicture = $(thisParent).find("picture");

    if ($(thisParent).find("picture").length > 0) {
      $(thisParent)
        .find("picture")
        .wrap('<div class="hero--header-wrap"></div>');
    } else {
      $(thisParent)
        .find(".hero--video")
        .wrap('<div class="hero--header-wrap"></div>');
    }
    $(thisParent)
      .find(".hero--header-wrap")
      .prepend('<h1 class="headline-1"></h1>');
    $(thisParent).find("h1.headline-1").text(thisHeadline);
  });

  $(".homepage-hero--slider").slick({
    autoplay: value === 0 ? false : true,
    autoplaySpeed: value,
    pauseOnHover: false,
  });

  window.addEventListener("load", function () {
    const menuItems = document.querySelectorAll("#block-sanjose-main-menu");

    const heroText = document.querySelectorAll(".homepage_slider--mobile");

    const featureEvent = document.querySelectorAll(".block-list--items li");


    if (menuItems.length > 0) {
      menuItems[0].style.display = "block";
    }

    if (heroText.length > 0) {
      heroText.forEach(function (ele) {
        ele.style.display = "block";
      });
    }

    if (featureEvent.length > 0) {
      featureEvent.forEach(function (ele) {
        ele.style.display = "block";
      });
    }
  });
})(jQuery);

