// The old weather.yahooapis.com and query.yahooapis.com for Yahoo Weather API has been retired. So implementing the new Yahoo Weather API.

(function ($){
var url = 'https://weather-ydn-yql.media.yahoo.com/forecastrss';
var method = 'GET';
var app_id = 'NUF4ie5g';
var consumer_key = 'dj0yJmk9dzJkVTQwZTg3Q21qJnM9Y29uc3VtZXJzZWNyZXQmc3Y9MCZ4PTZk';
var consumer_secret = 'b6209b73939732aed88db0cc49c7bd99e20e676d';
var concat = '&';
var query = {'location': 'San Jose, CA', 'format': 'json'};
var oauth = {
    'oauth_consumer_key': consumer_key,
    'oauth_nonce': Math.random().toString(36).substring(2),
    'oauth_signature_method': 'HMAC-SHA1',
    'oauth_timestamp': parseInt(new Date().getTime() / 1000).toString(),
    'oauth_version': '1.0'
};

var merged = {};
$.extend(merged, query, oauth);
// Note the sorting here is required
var merged_arr = Object.keys(merged).sort().map(function(k) {
  return [k + '=' + encodeURIComponent(merged[k])];
});
var signature_base_str = method
  + concat + encodeURIComponent(url)
  + concat + encodeURIComponent(merged_arr.join(concat));

var composite_key = encodeURIComponent(consumer_secret) + concat;
var hash = CryptoJS.HmacSHA1(signature_base_str, composite_key);
var signature = hash.toString(CryptoJS.enc.Base64);

oauth['oauth_signature'] = signature;
var auth_header = 'OAuth ' + Object.keys(oauth).map(function(k) {
  return [k + '="' + oauth[k] + '"'];
}).join(',');

$.ajax({
  url: url + '?' + $.param(query),
  headers: {
    'Authorization': auth_header,
    'Yahoo-App-Id': app_id 
  },
  method: 'GET',
  success: function(data){
    var currentTemp = data.current_observation.condition.temperature;
    document.getElementById("open-weather-temp").innerHTML = currentTemp + 'ºF';
  }
});

function bottomScroll() {
  var has = window.location.hash.replace("#", "");
  if (has) {
    var dataID = getHasName(has);
    var domElement = document.querySelector("section.block-list.shaded");
    var clickElem = document.querySelector(
      '.nearby-listing .nearby-listing--nav li[data-list-id="' + dataID + '"]'
    );
    var rect = domElement.getBoundingClientRect();
    $("html, body").animate({ scrollTop: rect.top }, 1000);
    clickElem.click();
  }
}
function getHasName(name) {
  if (name == "events") {
    return "Events";
  } else if (name == "restaurants") {
    return "Restaurants";
  } else if (name == "thingstodo") {
    return "Things To Do";
  } else if (name == "hotels") {
    return "Hotels";
  }
}
$(window).on("load", function () {
  setTimeout(function () {
    bottomScroll();
  }, 400);
});

})(jQuery);
